function maxDepth(root) {
  // Breadth-first search: count how many levels hold at least one node.
  let levels = 0;
  let level = root ? [root] : [];
  while (level.length > 0) {
    levels++;
    const below = [];
    for (const node of level) for (const child of node.children) below.push(child);
    level = below;
  }
  return levels;
}

